payload.message:
下面给你一段可直接用的 SystemVerilog，按你图里的规则做 `byte <-> bit` 对应（以 20-bit 像素、2 像素打包成 5 byte）：

```systemverilog
package raw20_map_pkg;

  typedef logic [19:0] pixel_t;
  typedef logic [7:0]  byte_t;

  // 2 pixels -> 5 bytes
  // B0 = P1[19:12]
  // B1 = P1[9:2]
  // B2 = P2[19:12]
  // B3 = P2[9:2]
  // B4 = {P2[1:0], P2[11:10], P1[1:0], P1[11:10]}

  task automatic pack_raw20_line(
    input  pixel_t pix_in[],   // size must be even
    output byte_t  bytes_out[]
  );
    int i, k, pairs;
    pairs = pix_in.size() / 2;
    bytes_out = new[pairs * 5];

    for (i = 0; i < pairs; i++) begin
      pixel_t p1, p2;
      p1 = pix_in[2*i];
      p2 = pix_in[2*i+1];
      k  = i * 5;

      bytes_out[k+0] = p1[19:12];
      bytes_out[k+1] = p1[9:2];
      bytes_out[k+2] = p2[19:12];
      bytes_out[k+3] = p2[9:2];
      bytes_out[k+4] = {p2[1:0], p2[11:10], p1[1:0], p1[11:10]};
    end
  endtask

  task automatic unpack_raw20_line(
    input  byte_t  bytes_in[], // size must be multiple of 5
    output pixel_t pix_out[]
  );
    int i, k, pairs;
    pairs = bytes_in.size() / 5;
    pix_out = new[pairs * 2];

    for (i = 0; i < pairs; i++) begin
      pixel_t p1, p2;
      k = i * 5;

      p1[19:12] = bytes_in[k+0];
      p1[9:2]   = bytes_in[k+1];
      p2[19:12] = bytes_in[k+2];
      p2[9:2]   = bytes_in[k+3];

      p2[1:0]   = bytes_in[k+4][7:6];
      p2[11:10] = bytes_in[k+4][5:4];
      p1[1:0]   = bytes_in[k+4][3:2];
      p1[11:10] = bytes_in[k+4][1:0];

      pix_out[2*i]   = p1;
      pix_out[2*i+1] = p2;
    end
  endtask

endpackage
```

如果你要，我可以下一步把它扩成 **4-lane（lane0~lane3）对齐版本**，把第二张图里的 lane 排布也一并写成可综合逻辑。

